function switchTab(n) {
  document.querySelectorAll('.tab-btn').forEach((b, i) => b.classList.toggle('active', i+1 === n));
  document.querySelectorAll('.part-container').forEach((p, i) => p.classList.toggle('active', i+1 === n));
  document.getElementById('mainContent').scrollTop = 0;
  currentCardIndex = 0;
  updateCardView();
}

let currentCardIndex = 0;
let cardsInCurrentPart = [];
function updateCardView() {
  // TỰ ĐỘNG TẠM DỪNG TẤT CẢ AUDIO ĐANG PHÁT TRÊN TRANG
  document.querySelectorAll('audio').forEach(audio => {
    audio.pause();
  });
  let activePart = document.querySelector('.part-container.active');
  if(!activePart) return;
  cardsInCurrentPart = Array.from(activePart.querySelectorAll('.q-card'));
  cardsInCurrentPart.forEach((card, index) => {
    card.style.display = (index === currentCardIndex) ? 'block' : 'none';
  });
  let btnPrev = document.getElementById('btnPrevCard');
  let btnNext = document.getElementById('btnNextCard');
  if(btnPrev) btnPrev.disabled = (currentCardIndex === 0);
  if(btnNext) btnNext.disabled = (currentCardIndex === cardsInCurrentPart.length - 1);
  document.getElementById('mainContent').scrollTop = 0;
}

function nextCard() {
  if (currentCardIndex < cardsInCurrentPart.length - 1) {
    currentCardIndex++;
    updateCardView();
  }
}

function prevCard() {
  if (currentCardIndex > 0) {
    currentCardIndex--;
    updateCardView();
  }
}

function toggleNavPanel() {
  const panel = document.getElementById('navPanel');
  const overlay = document.getElementById('navOverlay');
  panel.classList.toggle('show');
  if (panel.classList.contains('show')) overlay.classList.add('show');
  else overlay.classList.remove('show');
}

function scrollToQ(qId) {
  toggleNavPanel();
  let targetQuestion = document.getElementById(`text-q${qId}`) || document.getElementById(`card-${qId}`);
  if(targetQuestion) {
    let partContainer = targetQuestion.closest('.part-container');
    let partId = partContainer.id;
    let tabNum = parseInt(partId.replace('part', ''));
    document.querySelectorAll('.tab-btn').forEach((b, i) => b.classList.toggle('active', i+1 === tabNum));
    document.querySelectorAll('.part-container').forEach((p, i) => p.classList.toggle('active', i+1 === tabNum));
    cardsInCurrentPart = Array.from(partContainer.querySelectorAll('.q-card'));
    let targetCard = targetQuestion.closest('.q-card');
    let index = cardsInCurrentPart.indexOf(targetCard);
    if(index !== -1) {
      currentCardIndex = index;
      updateCardView();
    }
  }
}

