function executeSubmit() {
  isSubmitted = true;
  clearInterval(timerInterval);
  closeModal('confirmModal');
  let correctCount = 0;
  let totalRendered = 0;
  const keys = {};
  TOEIC_DATA.part1.forEach(q => keys[q.id] = q.answer || q.ans || q.correct);
  TOEIC_DATA.part2.forEach(q => keys[q.id] = q.answer || q.ans || q.correct);
  TOEIC_DATA.part3.forEach(p => p.questions.forEach(q => {
    let corrOpt = q.opts.find(o => o.isCorrect === true);
    keys[q.id] = q.answer || q.ans || q.correct || (corrOpt ? corrOpt.l : null);
  }));
  TOEIC_DATA.part4.forEach(p => p.questions.forEach(q => {
    let corrOpt = q.opts.find(o => o.isCorrect === true);
    keys[q.id] = q.answer || q.ans || q.correct || (corrOpt ? corrOpt.l : null);
  }));

  for(let i=1; i<=100; i++) {
    if(keys[i]) {
      totalRendered++;
      let isCorr = (userAnswers[i] === keys[i]);
      if(isCorr) correctCount++;
      document.querySelectorAll(`input[name="q${i}"]`).forEach(inp => {
        let lbl = inp.closest('.opt-label');
        if(inp.value === keys[i]) {
          lbl.classList.add('is-correct');
        } else if (inp.value === userAnswers[i] && !isCorr) {
          lbl.classList.add('is-wrong');
        }
      });
      let exp = document.getElementById(`exp-${i}`);
      if(exp) exp.classList.add('show');
      let nav = document.getElementById(`nav-${i}`);
      if(nav) {
        nav.classList.remove('answered');
        nav.classList.add(isCorr ? 'correct' : 'wrong');
      }
      let qText = document.getElementById(`text-q${i}`);
      if(qText) qText.classList.remove('hidden-in-mock');
      document.querySelectorAll(`input[name="q${i}"]`).forEach(inp => {
        let span = inp.closest('.opt-label').querySelector('span');
        if(span) span.classList.remove('hidden-in-mock');
      });
    }
  }

  TOEIC_DATA.part3.forEach(p => { let ep = document.getElementById(`exp-passage-${p.id}`); if(ep) ep.classList.add('show'); });
  TOEIC_DATA.part4.forEach(p => { let ep = document.getElementById(`exp-passage-${p.id}`); if(ep) ep.classList.add('show'); });

  let toeicScore = getScaledScore(correctCount, totalRendered);

  // Tính toán số lượt thi của bài này
  let history = JSON.parse(localStorage.getItem(HISTORY_KEY)) || [];
  let currentAttemptNum = history.length + (isReviewingMode ? 0 : 1);
  let attemptText = `<div style="font-size: 14px; font-weight: 700; color: var(--primary); margin-bottom: 6px;">🎉 Bạn đã hoàn thành Lượt thi #${currentAttemptNum}!</div>`;

  document.getElementById('scoreDisplay').innerText = `${correctCount}/${totalRendered}`;
  document.getElementById('scoreComment').innerHTML = `
    ${attemptText}
    Điểm TOEIC Listening dự kiến: <b>${toeicScore}</b>/495
  `;
  document.getElementById('resultModal').classList.add('show');
  document.getElementById('headerSubmitBtn').style.display = 'none';
  let cardNavArea = document.getElementById('cardNavArea');
  if (cardNavArea) cardNavArea.style.display = 'flex';
  if(!isReviewingMode) {
    saveAttemptToHistory(correctCount, totalRendered, userAnswers);
  }
  if (mockAudioList.length > 0) {
    mockAudioList.forEach(a => a.pause());
    document.querySelectorAll('audio').forEach(a => a.setAttribute('controls', 'controls'));
  }
}

function initResizer(resizer, leftElement, container) {
  let isDragging = false;
  resizer.addEventListener('mousedown', function(e) {
    isDragging = true;
    resizer.classList.add('dragging');
    document.body.style.cursor = 'col-resize';
    document.body.style.userSelect = 'none';
  });
  document.addEventListener('mousemove', function(e) {
    if (!isDragging) return;
    const containerRect = container.getBoundingClientRect();
    let newWidth = ((e.clientX - containerRect.left) / containerRect.width) * 100;
    if (newWidth < 25) newWidth = 25;
    if (newWidth > 75) newWidth = 75;
    leftElement.style.flex = `0 0 ${newWidth}%`;
  });
  document.addEventListener('mouseup', function() {
    if (isDragging) {
      isDragging = false;
      resizer.classList.remove('dragging');
      document.body.style.cursor = 'default';
      document.body.style.userSelect = 'auto';
    }
  });
}

