async function syncHistoryWithCloud() {
  if (!currentUserEmail) return;
  try {
    const qCloud = query(
      collection(db, "user_test_histories"),
      where("email", "==", currentUserEmail),
      where("testId", "==", testId)
    );
    const querySnapshot = await getDocs(qCloud);
    let cloudHistory = [];
    querySnapshot.forEach(docSnap => {
      cloudHistory.push({ id: docSnap.id, ...docSnap.data() });
    });
    let localHistory = JSON.parse(localStorage.getItem(HISTORY_KEY)) || [];
    // Hợp nhất danh sách không để trùng lặp (dựa trên localId / timestamp)
    let merged = [...localHistory];
    cloudHistory.forEach(cItem => {
      if (!merged.some(lItem => lItem.id === cItem.localId)) {
        merged.push({
          id: cItem.localId,
          skill: cItem.skill || "Listening",
          testName: cItem.testName || "TOEIC Listening Test 1",
          partName: cItem.partName || "Full",
          attemptNum: cItem.attemptNum || 1, // Thêm dòng này
          correctQ: cItem.correctQ || cItem.correct,
          totalQ: cItem.totalQ || cItem.total,
          score: cItem.score,
          date: cItem.date,
          time: cItem.time,
          Time: cItem.Time || cItem.time,
          timeTaken: cItem.timeTaken || "00:00",
          timestamp: cItem.timestamp || cItem.localId,
          answers: cItem.answers
        });
      }
    });
    // Sắp xếp lượt làm mới nhất lên đầu trang
    merged.sort((a, b) => b.id - a.id);
    localStorage.setItem(HISTORY_KEY, JSON.stringify(merged));
    // Đẩy ngược những bài làm offline từ Local lên Cloud
    for (let localItem of localHistory) {
      if (!cloudHistory.some(cItem => cItem.localId === localItem.id)) {
        await addDoc(collection(db, "user_test_histories"), {
          email: currentUserEmail,
          testId: testId,
          localId: localItem.id,
          skill: localItem.skill,
          testName: localItem.testName,
          partName: localItem.partName,
          attemptNum: localItem.attemptNum || 1, // Thêm dòng này
          correctQ: localItem.correctQ,
          totalQ: localItem.totalQ,
          score: localItem.score,
          date: localItem.date,
          time: localItem.time,
          Time: localItem.Time,
          timeTaken: localItem.timeTaken,
          timestamp: localItem.timestamp,
          answers: localItem.answers
        });
      }
    }
  } catch (err) {
    console.error("Lỗi đồng bộ đám mây: ", err);
  }
}

